/*
Day #7: Flexible Graph
https://openprocessing.org/sketch/2385182
https://mathober.com/
https://openprocessing.org/curation/87980
*/

// size, num, layers
let S, N = 5, L = 3;

function setup() {
  createCanvas(windowWidth, windowHeight);
	describe("overlapping layers of grid of colored nodes in different rotations with same distace to the next node (trapez)");
  frameRate(60);
  S = ~~(max(width, height) / N);
  stroke("rgba(245,245,220,0.25)");
  strokeWeight(2);
  noStroke();
  loop();
  redraw();
}

function draw() {
  background(32);
  for (let i = 0; i < L; i++) {    
    const vHor = createVector(S, 0).rotate((noise(S + i, 1, frameCount) - 0.5) * HALF_PI);
    const vVer = createVector(0, S).rotate((noise(S, i, frameCount) - 0.5) * HALF_PI);
    drawNodes(createVector(0, 0), vHor, vVer, i % 2 === 0);
  }
  L = random(1, 6);
  // noLoop() removed for animation
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}


function drawNodes(p, vHor, vVer, PRPL = true) {
  let p1, p2, p3, p4;

  p1 = p.copy();
  p2 = p1.copy().add(vHor);
  p4 = p2.copy().add(vVer);
  while (p1.y < height + S) {
    p3 = p1.copy().add(vVer);
    // console.log(` #p1 ${p1.y}`)
    p = p3.copy(); // next row starts with p3
    while (p1.x < width + S) {      
      p2 = p1.copy().add(vHor);
      p3 = p1.copy().add(vVer);
      p4 = p2.copy().add(vVer);

      // console.log(`p(${nf(p1.x, 0, 2)},${nf(p1.y, 0, 2)}) `);
      line(p1.x, p1.y, p2.x, p2.y);
      line(p1.x, p1.y, p3.x, p3.y);

      fill(~~(32, noise(p1.x/333+234234)*256), ~~(noise(p1.y/222+423423)*256), 64)
      if (PRPL) fill(~~(noise(p1.x/333+234234)*256), 32, ~~(noise(p1.y/222+423423)*256), 64)

      beginShape();
      vertex(p1.x, p1.y);
      vertex(p2.x, p2.y);
      vertex(p4.x, p4.y);
      vertex(p3.x, p3.y);
      endShape(CLOSE);
      p1 = p2.copy();
    }   
    p1 = p.copy(); // next row starts with p / p3
  }

  // p4 = p2.copy().add(vVer);

  // line(p2.x, p2.y, p4.x, p4.y);
  // line(p3.x, p3.y, p4.x, p4.y);
}
